import { z } from "zod";
import { IsoDate, LatLon, Provenance, SourceRef } from "./evidence.ts";

/**
 * Signal evidence layer (signal-evidence.json). Records, per signal, what each source says and
 * how far it is corroborated, as separate claims: identity, position, direction, berth
 * association and track context. Corroborating one claim never upgrades another (a confirmed
 * identity says nothing about position). Generated by a reconciliation tool from sourced
 * inputs; it annotates the infrastructure layer and never modifies it. See DATA_MODEL.md.
 */

/**
 * How a claim stands against the other evidence available, independent of its evidence level:
 * - corroborated:   a second, independent source states the same claim
 * - consistent:     a cross-check against another source agreed (e.g. a berth step fits the track)
 * - consistent_with_reversal: agrees only if trains reverse at a dead end (a reasoned check)
 * - single_source:  only one source; nothing to test it against
 * - ambiguous:      more than one interpretation fits (e.g. two candidate berths)
 * - disputed:       some cross-checks agree and others contradict
 * - contradicted:   cross-checks contradict the claim and no alternative explanation was found
 * - unresolved:     tested, but the test could not decide (e.g. heuristic limits)
 * - not_assessed:   no test was possible
 * A claim may be `verified` only when its assessment is `corroborated`.
 */
export const CLAIM_ASSESSMENTS = [
  "corroborated",
  "consistent",
  "consistent_with_reversal",
  "single_source",
  "ambiguous",
  "disputed",
  "contradicted",
  "unresolved",
  "not_assessed",
] as const;
export const ClaimAssessment = z.enum(CLAIM_ASSESSMENTS);
export type ClaimAssessment = z.infer<typeof ClaimAssessment>;

const claim = <T extends z.ZodType>(value: T) =>
  z
    .object({
      value: value.nullable(),
      provenance: Provenance,
      assessment: ClaimAssessment,
      /** What the cross-checks found, one statement each. */
      findings: z.array(z.string()).default([]),
      /** What the evidence cannot show. */
      limitations: z.array(z.string()).default([]),
    })
    .superRefine((c, ctx) => {
      if (c.provenance.evidence === "verified" && c.assessment !== "corroborated")
        ctx.addIssue({
          code: "custom",
          message: `verified evidence requires assessment "corroborated", not "${c.assessment}"`,
        });
    });

/** SMART EVENT code, decoded: A/B = arrive/depart Up, C/D = arrive/depart Down. */
export const BerthEvent = z.object({
  raw: z.string(),
  kind: z.enum(["arrive", "depart"]).nullable(),
  direction: z.enum(["up", "down"]).nullable(),
});

export const STEP_RESULTS = [
  "consistent", // path in the first signal's direction reaches the second from behind
  "consistent_alternative_heuristic", // as above, but only under the "smooth" junction rule
  "unresolved_slip_diagonal", // a path exists only through a single slip's unknown diagonal
  "reversal_at_dead_end", // head-on arrival into a dead-end road, then departure the other way
  "contradicts_direction", // head-on arrival only, with no reversal explanation
  "no_path", // no path under either junction rule
  "signal_direction_unknown",
  "one_side_unmatched",
  "both_unmatched",
] as const;
export const StepResult = z.enum(STEP_RESULTS);
export type StepResult = z.infer<typeof StepResult>;

/** One SMART berth step, with raw values preserved, tested against OSM track. */
export const BerthStepEvidence = z.object({
  id: z.string().min(1),
  td: z.string(),
  fromBerth: z.string(),
  toBerth: z.string(),
  stanox: z.string(),
  stanme: z.string(),
  stepType: z.string(),
  event: BerthEvent,
  platform: z.string(),
  fromLine: z.string(),
  toLine: z.string(),
  berthOffset: z.string(),
  route: z.string(),
  /** SMART COMMENT, raw. Free text, usually a date; not a reliable record date. */
  comment: z.string(),
  fromSignalId: z.string().nullable(),
  toSignalId: z.string().nullable(),
  result: StepResult,
  distanceM: z.number().nullable(),
  /**
   * Whether the test discriminates the first signal's direction: true when no path reaches
   * the second signal if the train leaves the first one against its OSM direction (either
   * junction rule). null when not tested.
   */
  fromDirectionDiscriminates: z.boolean().nullable(),
  /** Junction and signal nodes passed (plain nodes omitted), when a path was found. */
  keyNodeIds: z.array(z.string()).default([]),
  explanation: z.string(),
  provenance: Provenance,
});
export type BerthStepEvidence = z.infer<typeof BerthStepEvidence>;

export const BerthAssociation = z.object({
  td: z.string(),
  /** Berth id exactly as in the source, e.g. "0327" or "X323". */
  berth: z.string(),
  berthKind: z.enum(["numeric", "lettered", "other"]),
  match: z.enum(["unambiguous", "ambiguous"]),
  /** Ids of the BerthStepEvidence records that test this association. */
  stepIds: z.array(z.string()).default([]),
  claim: claim(z.string()),
});

export const TrackRun = z.object({
  nodeId: z.string(),
  nodeKind: z.string(),
  degree: z.number(),
  distanceM: z.number(),
});

export const SignalEvidenceRecord = z.object({
  signalId: z.string().min(1),
  /** OSM ref exactly as tagged, or null. */
  rawRef: z.string().nullable(),
  parsedRef: z.object({ prefix: z.string(), number: z.number(), suffix: z.string() }).nullable(),
  /** Raw OSM signal tags relevant to the claims (direction, fixme, kind), unmodified. */
  rawTags: z.record(z.string(), z.string()).default({}),
  identity: claim(z.string()),
  position: claim(LatLon),
  /** Value: the node the signal faces towards (as in infrastructure.json). */
  direction: claim(z.string()),
  /** Value: what plain track leads to ahead of and behind the signal. */
  trackContext: claim(z.object({ ahead: TrackRun.nullable(), behind: TrackRun.nullable() })),
  berths: z.array(BerthAssociation).default([]),
});
export type SignalEvidenceRecord = z.infer<typeof SignalEvidenceRecord>;

/** A berth with no unambiguous signal, kept so gaps stay visible. */
export const UnmatchedBerth = z.object({
  td: z.string(),
  berth: z.string(),
  berthKind: z.enum(["numeric", "lettered", "other"]),
  match: z.enum(["ambiguous", "unmatched"]),
  candidateSignalIds: z.array(z.string()).default([]),
  stanox: z.array(z.string()),
  reason: z.string(),
});

/** A signal named by a timing-point source (e.g. CORPUS "CARLISLE CE 404 SIGNAL"). */
export const NamedSignal = z.object({
  plate: z.string(),
  description: z.string(),
  tiploc: z.string(),
  stanox: z.string(),
  osmSignalIds: z.array(z.string()),
  numericBerthAtSameStanox: z.boolean(),
  provenance: Provenance,
});

export const SignalEvidenceFile = z.object({
  datasetId: z.string().min(1),
  generated: IsoDate,
  /** How the file was produced, and the rules applied. */
  method: z.string().min(1),
  inputs: z.array(SourceRef).min(1),
  scope: z.object({
    td: z.string(),
    signalPrefix: z.string(),
    /** STANOX treated as in the area, with the name used to select it. */
    stanox: z.record(z.string(), z.string()),
  }),
  signals: z.array(SignalEvidenceRecord),
  steps: z.array(BerthStepEvidence),
  unmatchedBerths: z.array(UnmatchedBerth),
  namedSignals: z.array(NamedSignal).default([]),
});
export type SignalEvidenceFile = z.infer<typeof SignalEvidenceFile>;
